/**
 * Utility functions for deterministic saga ID generation.
 * 
 * Generates consistent UUID-like identifiers from input parts using SHA-256 hashing.
 * This ensures the same inputs always produce the same sagaId, enabling idempotent saga creation.
 */

/**
 * Generate a deterministic saga ID from the provided parts.
 * 
 * The ID is generated by:
 * 1. Normalizing each part (trim, lowercase)
 * 2. Joining with ':' separator
 * 3. Computing SHA-256 hash
 * 4. Formatting as UUID-like string (8-4-4-4-12 hex format)
 * 
 * Special characters in input are fully supported - they are included in the hash input.
 * 
 * @param parts - String parts to include in the hash (e.g., name, projectId, materialId)
 * @returns A Promise resolving to a UUID-formatted hex string (36 characters)
 * 
 * @example
 * const sagaId = await generateDeterministicSagaId('Foundation Concrete', 'proj-123', 'mat-456')
 * // Always returns: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890' (same inputs = same output)
 */
export async function generateDeterministicSagaId(...parts: (string | null | undefined)[]): Promise<string> {
  // Normalize: trim, lowercase, filter empty
  const normalized = parts
    .map(p => p?.trim().toLowerCase() || '')
    .filter(p => p.length > 0)
    .join(':');

  if (normalized.length === 0) {
    throw new Error('Saga ID generation requires at least one non-empty part');
  }

  return sha256ToUuid(normalized);
}

/**
 * Convert a SHA-256 hash to UUID format.
 */
async function sha256ToUuid(input: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(input);
  
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  
  // Take first 16 bytes and format as UUID
  const hex = hashArray.slice(0, 16).map(b => b.toString(16).padStart(2, '0')).join('');
  
  return formatAsUuid(hex);
}

/**
 * Format a hex string as UUID (8-4-4-4-12).
 */
function formatAsUuid(hex: string): string {
  // Ensure we have at least 32 hex characters
  const padded = hex.padEnd(32, '0').slice(0, 32);
  
  return `${padded.slice(0, 8)}-${padded.slice(8, 12)}-${padded.slice(12, 16)}-${padded.slice(16, 20)}-${padded.slice(20, 32)}`;
}

/**
 * Check if a saga name is valid.
 * 
 * @param name - The saga name to validate
 * @returns Object with validity status and error message
 */
export function validateSagaName(name: string): { valid: boolean; error?: string } {
  if (!name || name.trim().length === 0) {
    return { valid: false, error: 'Saga name is required' };
  }
  
  if (name.trim().length < 2) {
    return { valid: false, error: 'Saga name must be at least 2 characters' };
  }
  
  if (name.trim().length > 100) {
    return { valid: false, error: 'Saga name must be less than 100 characters' };
  }
  
  // Special characters are fully supported - no restrictions needed
  // The hash function handles any valid UTF-8 string
  
  return { valid: true };
}

/**
 * Normalize a saga name for display and hashing.
 * 
 * @param name - The raw saga name
 * @returns The trimmed and normalized name
 */
export function normalizeSagaName(name: string): string {
  return name.trim();
}